import { mkdir, readdir, readFile, rm, writeFile } from "node:fs/promises";
import { basename, dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { compile } from "json-schema-to-typescript";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const schemaDir = join(root, "schemas");
const outDir = join(root, "ts");

const banner =
  "// Code generated by make contracts from packages/contracts/schemas. DO NOT EDIT.";

async function schemaFiles(dir) {
  const entries = await readdir(dir, { withFileTypes: true });
  const files = await Promise.all(
    entries.map((e) => {
      const p = join(dir, e.name);
      if (e.isDirectory()) return schemaFiles(p);
      return e.name.endsWith(".json") ? [p] : [];
    }),
  );
  return files.flat().sort();
}

await rm(outDir, { recursive: true, force: true });
await mkdir(outDir, { recursive: true });

const modules = [];
for (const file of await schemaFiles(schemaDir)) {
  const schema = JSON.parse(await readFile(file, "utf8"));
  const ts = await compile(schema, schema.title, {
    bannerComment: banner,
    cwd: dirname(file),
    // Without this, maxItems turns arrays into unions of fixed-length tuples.
    maxItems: -1,
    unknownAny: true,
    additionalProperties: false,
  });
  const name = relative(schemaDir, file).replaceAll("/", ".").replace(/\.json$/, "");
  await writeFile(join(outDir, `${name}.ts`), ts);
  modules.push(name);
}

const index = [banner, "", ...modules.map((m) => `export type * from "./${m}";`), ""];
await writeFile(join(outDir, "index.ts"), index.join("\n"));
console.log(`wrote ${modules.length} modules to ${basename(outDir)}/`);
